CREATE TABLE admin_users (id BIGSERIAL PRIMARY KEY,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'support',totp_secret TEXT,totp_enabled BOOLEAN NOT NULL DEFAULT false,created_at TIMESTAMPTZ DEFAULT now(),last_login_at TIMESTAMPTZ);
ALTER TABLE admin_users ADD COLUMN IF NOT EXISTS totp_secret TEXT;
ALTER TABLE admin_users ADD COLUMN IF NOT EXISTS totp_enabled BOOLEAN NOT NULL DEFAULT false;
CREATE TABLE users (id BIGSERIAL PRIMARY KEY,external_code TEXT UNIQUE NOT NULL,email TEXT UNIQUE,phone TEXT,birth_date DATE,password_hash TEXT,promo_code TEXT,country_code CHAR(2) NOT NULL DEFAULT 'AZ',language_code CHAR(2) NOT NULL DEFAULT 'az',currency CHAR(3) NOT NULL DEFAULT 'AZN',balance NUMERIC(18,2) NOT NULL DEFAULT 0,kyc_status TEXT NOT NULL DEFAULT 'pending',created_at TIMESTAMPTZ DEFAULT now(),updated_at TIMESTAMPTZ DEFAULT now());
ALTER TABLE users ADD COLUMN IF NOT EXISTS phone TEXT;
ALTER TABLE users ADD COLUMN IF NOT EXISTS birth_date DATE;
ALTER TABLE users ADD COLUMN IF NOT EXISTS promo_code TEXT;
CREATE TABLE IF NOT EXISTS kyc_documents (id BIGSERIAL PRIMARY KEY,user_id BIGINT REFERENCES users(id),document_type TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',file_url TEXT,reviewed_by BIGINT REFERENCES admin_users(id),reviewed_at TIMESTAMPTZ,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS responsible_limits (user_id BIGINT PRIMARY KEY REFERENCES users(id),deposit_daily NUMERIC(18,2),deposit_weekly NUMERIC(18,2),loss_daily NUMERIC(18,2),session_minutes INT,self_excluded_until TIMESTAMPTZ,updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS loto_rounds (id BIGSERIAL PRIMARY KEY,round_code TEXT UNIQUE NOT NULL,status TEXT NOT NULL DEFAULT 'open',ticket_price NUMERIC(18,2) NOT NULL DEFAULT 1.00,draw_interval_seconds INT NOT NULL DEFAULT 120,started_at TIMESTAMPTZ,closed_at TIMESTAMPTZ,winning_numbers INT[] DEFAULT '{}',jackpot_amount NUMERIC(18,2) NOT NULL DEFAULT 0,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS loto_tickets (id BIGSERIAL PRIMARY KEY,round_id BIGINT REFERENCES loto_rounds(id),user_id BIGINT REFERENCES users(id),numbers INT[] NOT NULL,ticket_price NUMERIC(18,2) NOT NULL,external_id TEXT UNIQUE NOT NULL,status TEXT NOT NULL DEFAULT 'active',created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS loto_payouts (id BIGSERIAL PRIMARY KEY,round_id BIGINT REFERENCES loto_rounds(id),ticket_id BIGINT REFERENCES loto_tickets(id),user_id BIGINT REFERENCES users(id),pattern TEXT NOT NULL,amount NUMERIC(18,2) NOT NULL,transaction_id TEXT UNIQUE NOT NULL,status TEXT NOT NULL DEFAULT 'pending',created_at TIMESTAMPTZ DEFAULT now());
ALTER TABLE users ADD COLUMN IF NOT EXISTS country_code CHAR(2) NOT NULL DEFAULT 'AZ';
ALTER TABLE users ADD COLUMN IF NOT EXISTS language_code CHAR(2) NOT NULL DEFAULT 'az';
CREATE TABLE wallet_transactions (id BIGSERIAL PRIMARY KEY,user_id BIGINT REFERENCES users(id),external_id TEXT UNIQUE,kind TEXT NOT NULL,amount NUMERIC(18,2) NOT NULL,balance_before NUMERIC(18,2) NOT NULL,balance_after NUMERIC(18,2) NOT NULL,status TEXT NOT NULL,provider TEXT,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE audit_logs (id BIGSERIAL PRIMARY KEY,admin_id BIGINT REFERENCES admin_users(id),action TEXT NOT NULL,entity TEXT,entity_id TEXT,metadata JSONB,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS affiliates (id BIGSERIAL PRIMARY KEY,code TEXT UNIQUE NOT NULL,name TEXT NOT NULL,commission_rate NUMERIC(5,2) NOT NULL DEFAULT 5.00,status TEXT NOT NULL DEFAULT 'active',created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS affiliate_referrals (id BIGSERIAL PRIMARY KEY,affiliate_id BIGINT REFERENCES affiliates(id),user_id BIGINT REFERENCES users(id),created_at TIMESTAMPTZ DEFAULT now(),UNIQUE(affiliate_id,user_id));
CREATE TABLE IF NOT EXISTS affiliate_commissions (id BIGSERIAL PRIMARY KEY,affiliate_id BIGINT REFERENCES affiliates(id),user_id BIGINT REFERENCES users(id),external_id TEXT UNIQUE NOT NULL,ggr_amount NUMERIC(18,2) NOT NULL,commission_rate NUMERIC(5,2) NOT NULL,commission_amount NUMERIC(18,2) NOT NULL,status TEXT NOT NULL DEFAULT 'pending',created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS bonuses (id BIGSERIAL PRIMARY KEY,title TEXT NOT NULL,kind TEXT NOT NULL DEFAULT 'deposit',amount NUMERIC(18,2) NOT NULL DEFAULT 0,wager_multiplier NUMERIC(8,2) NOT NULL DEFAULT 1,active BOOLEAN NOT NULL DEFAULT false,starts_at TIMESTAMPTZ,ends_at TIMESTAMPTZ,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS promo_codes (id BIGSERIAL PRIMARY KEY,code TEXT UNIQUE NOT NULL,bonus_id BIGINT REFERENCES bonuses(id),usage_limit INT,used_count INT NOT NULL DEFAULT 0,active BOOLEAN NOT NULL DEFAULT false,expires_at TIMESTAMPTZ,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS provider_controls (code TEXT PRIMARY KEY,name TEXT NOT NULL,enabled BOOLEAN NOT NULL DEFAULT false,mode TEXT NOT NULL DEFAULT 'staging',updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS payment_controls (code TEXT PRIMARY KEY,name TEXT NOT NULL,enabled BOOLEAN NOT NULL DEFAULT false,mode TEXT NOT NULL DEFAULT 'staging',currency CHAR(3) NOT NULL DEFAULT 'AZN',updated_at TIMESTAMPTZ DEFAULT now());
ALTER TABLE users ADD COLUMN IF NOT EXISTS affiliate_id BIGINT REFERENCES affiliates(id);
